package com.bank.report;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PeekDemo {
    private static final Logger log = Logger.getLogger("Peek");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", new BigDecimal("1000000")),
            new Employee("Priya", new BigDecimal("250000")),
            new Employee("Amit", new BigDecimal("40000")));
        EmployeeReportService service = new EmployeeReportService(log);

        List<String> result = service.highEarners(staff);
        log.info(() -> "High earners: " + result);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final BigDecimal salary;
    Employee(String name, BigDecimal salary) { this.name = name; this.salary = salary; }
    String getName() { return name; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/EmployeeReportService.java ───
class EmployeeReportService {
    private final Logger log;
    EmployeeReportService(Logger log) { this.log = log; }

    List<String> highEarners(List<Employee> staff) {
        return staff.stream()
            .peek(e -> log.fine(() -> "entering filter: " + e.getName()))   // watch input
            .filter(e -> e.getSalary().compareTo(new BigDecimal("50000")) > 0)
            .peek(e -> log.fine(() -> "survived filter: " + e.getName()))   // watch survivors
            .map(Employee::getName)
            .collect(java.util.stream.Collectors.toList());
    }
}
